package io.knowledgebrain.learning;
import java.time.*;import java.sql.Timestamp;import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.learning.evidencesession.v1.*;

/** Independent Learning relationship; never mutates evidence, sessions or progress. */
final class EvidenceSessionStore {
 record Link(UUID linkId,UUID evidenceId,String evidenceKind,UUID roadmapId,UUID spaceId,UUID nodeId,String nodeTitle,String visibility,String state,long version,UUID sessionId,Long sessionVersion,String sessionNodeTitle,String startedAt,String endedAt,Long durationSeconds,String createdAt,String updatedAt){}
 record Revision(UUID revisionId,UUID linkId,long version,UUID actorId,String occurredAt,Link snapshot){}
 record Input(UUID sessionId,Long sessionVersion){}
 private record Head(UUID node,String title,String state){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final RoadmapStore roadmaps;private final LearningStudyStore sessions;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 EvidenceSessionStore(DataSource ds,Clock clock,RoadmapStore roadmaps,LearningStudyStore sessions){jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.roadmaps=roadmaps;this.sessions=sessions;this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Evidence session link unavailable");}
 private Head evidence(UUID space,UUID roadmap,UUID evidence,String kind){RoadmapGraph.id(space);RoadmapGraph.id(roadmap);RoadmapGraph.id(evidence);if(!Set.of("NOTE","CONCEPT","MEDIA","GITHUB").contains(kind))throw LearningStudyStore.bad();var rows=jdbc.query("SELECT e.node_id,e.state,v.snapshot::text FROM roadmap r JOIN learning_evidence e ON e.roadmap_id=r.roadmap_id JOIN learning_evidence_revision v ON v.evidence_id=e.evidence_id AND v.version=e.version WHERE r.space_id=? AND r.roadmap_id=? AND e.evidence_id=? AND e.kind=?",(rs,n)->new Head(rs.getObject(1,UUID.class),json.readTree(rs.getString(3)).path("nodeTitle").asString(),rs.getString(2)),space,roadmap,evidence,kind);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Link read(UUID space,UUID roadmap,UUID evidence,String kind,Head head){var rows=jdbc.query("SELECT l.link_id,l.version,l.state,v.snapshot::text FROM evidence_study_session l JOIN evidence_study_session_revision v ON v.link_id=l.link_id AND v.version=l.version WHERE l.evidence_id=?",(rs,n)->{var v=json.readValue(rs.getString(4),Link.class);if(!v.linkId().equals(rs.getObject(1,UUID.class))||v.version()!=rs.getLong(2)||!v.state().equals(rs.getString(3))||!space.equals(v.spaceId())||!roadmap.equals(v.roadmapId())||!evidence.equals(v.evidenceId())||!kind.equals(v.evidenceKind())||!head.node().equals(v.nodeId())||!"PRIVATE".equals(v.visibility()))throw new IllegalStateException("Evidence session revision mismatch");return v;},evidence);return rows.isEmpty()?new Link(null,evidence,kind,roadmap,space,head.node(),head.title(),"PRIVATE","UNLINKED",0,null,null,null,null,null,null,null,null):rows.getFirst();}
 Link get(UUID space,UUID roadmap,UUID evidence,String kind){return read(space,roadmap,evidence,kind,evidence(space,roadmap,evidence,kind));}
 Link change(UUID space,UUID roadmap,UUID evidence,String kind,UUID actor,long expected,Input input,String trace){RoadmapGraph.id(actor);if(expected<0||input==null||trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw LearningStudyStore.bad();if(input.sessionId()==null){if(input.sessionVersion()!=null)throw LearningStudyStore.bad();}else{RoadmapGraph.id(input.sessionId());if(input.sessionVersion()==null||input.sessionVersion()<1)throw LearningStudyStore.bad();}
  return tx.execute(status->{var root=roadmaps.lock(space,roadmap);if(!root.state().equals("ACTIVE"))throw missing();var head=evidence(space,roadmap,evidence,kind);var prior=read(space,roadmap,evidence,kind,head);if(prior.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Evidence session link changed; inspect latest");if(Objects.equals(prior.sessionId(),input.sessionId())&&Objects.equals(prior.sessionVersion(),input.sessionVersion()))return prior;
   LearningStudyStore.Session session=null;if(input.sessionId()!=null){if(!head.state().equals("ACTIVE")||root.nodes().stream().noneMatch(n->n.nodeId().equals(head.node())))throw missing();session=sessions.session(space,roadmap,input.sessionId());if(!head.node().equals(session.nodeId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Session must belong to the same learning node");if(session.version()!=input.sessionVersion())throw new ResponseStatusException(HttpStatus.CONFLICT,"Session version changed; select latest");}
   var now=clock.instant();var value=new Link(prior.linkId()==null?ids.next():prior.linkId(),evidence,kind,roadmap,space,head.node(),head.title(),"PRIVATE",session==null?"UNLINKED":"LINKED",Math.addExact(prior.version(),1),input.sessionId(),input.sessionVersion(),session==null?null:session.nodeTitle(),session==null?null:session.startedAt(),session==null?null:session.endedAt(),session==null?null:session.durationSeconds(),prior.createdAt()==null?now.toString():prior.createdAt(),now.toString());
   if(prior.linkId()==null)jdbc.update("INSERT INTO evidence_study_session VALUES (?,?,?,?,?,?)",value.linkId(),evidence,value.version(),value.state(),value.sessionId(),value.sessionVersion());else jdbc.update("UPDATE evidence_study_session SET version=?,state=?,session_id=?,session_version=? WHERE link_id=?",value.version(),value.state(),value.sessionId(),value.sessionVersion(),value.linkId());revision(value,actor,trace,now);return value;
  });
 }
 List<Revision> history(UUID space,UUID roadmap,UUID evidence,String kind,long before,int limit){var value=get(space,roadmap,evidence,kind);if(before<1||limit<1||limit>10)throw LearningStudyStore.bad();if(value.linkId()==null)return List.of();return jdbc.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM evidence_study_session_revision WHERE link_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),value.linkId(),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Link.class)),value.linkId(),before,limit);}
 private void revision(Link v,UUID actor,String trace,Instant now){UUID revision=ids.next();jdbc.update("INSERT INTO evidence_study_session_revision VALUES (?,?,?,?,?,?::jsonb)",revision,v.linkId(),v.version(),actor,Timestamp.from(now),json.writeValueAsString(v));if(v.evidenceKind().equals("GITHUB")){GitHubEvidenceEvents.session(jdbc,ids,v,revision,actor,trace,now);return;}var p=EvidenceSessionChangedPayloadV1.newBuilder().setLinkId(v.linkId().toString()).setEvidenceId(v.evidenceId().toString()).setEvidenceKind(v.evidenceKind()).setRoadmapId(v.roadmapId().toString()).setNodeId(v.nodeId().toString()).setNodeTitle(v.nodeTitle()).setVisibility("PRIVATE").setState(v.state()).setVersion(v.version()).setRevisionId(revision.toString()).setCreatedAt(v.createdAt()).setUpdatedAt(v.updatedAt());if(v.sessionId()!=null)p.setSessionId(v.sessionId().toString()).setSessionVersion(v.sessionVersion()).setSessionNodeTitle(v.sessionNodeTitle()).setStartedAt(v.startedAt()).setEndedAt(v.endedAt()).setDurationSeconds(v.durationSeconds());var e=EvidenceSessionEventEnvelopeV1.newBuilder().setEventId(ids.next().toString()).setEventType("EvidenceStudySessionChanged").setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("learning-service").setAggregateType("EvidenceStudySession").setAggregateId(v.linkId().toString()).setSpaceId(v.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(p.build().toByteString()).build();jdbc.update("INSERT INTO outbox_event VALUES (?,'evidence-session',?,'EvidenceStudySessionChanged',?,?,'learning','evidence-session-events','1',?)",UUID.fromString(e.getEventId()),v.linkId(),Timestamp.from(now),trace,e.toByteArray());}
}
